-- Sin materias, sedes regionales, concesiones o clasificaciones nominales por defecto.
CREATE TABLE institution_matter(id VARCHAR(64) PRIMARY KEY,label VARCHAR(120) NOT NULL,functional_unit VARCHAR(8) NOT NULL,valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,status VARCHAR(16) NOT NULL,authority_revision BIGINT NOT NULL,FOREIGN KEY(functional_unit) REFERENCES core_unit(code),FOREIGN KEY(authority_revision) REFERENCES authority_batch(revision),CHECK(functional_unit IN ('UPR','UPD')),CHECK(valid_until>valid_from),CHECK(status IN ('ACTIVA','SUSPENDIDA')));
CREATE TABLE matter_regional_site(site_id VARCHAR(40) PRIMARY KEY,valid_from BIGINT NOT NULL,valid_until BIGINT NOT NULL,status VARCHAR(16) NOT NULL,authority_revision BIGINT NOT NULL,FOREIGN KEY(site_id) REFERENCES core_site(id),FOREIGN KEY(authority_revision) REFERENCES authority_batch(revision),CHECK(valid_until>valid_from),CHECK(status IN ('ACTIVA','SUSPENDIDA')));
CREATE TABLE authority_matter_mandate(batch_revision BIGINT NOT NULL,mandate_id VARCHAR(64) NOT NULL,matter_id VARCHAR(64) NOT NULL,PRIMARY KEY(batch_revision,mandate_id),FOREIGN KEY(batch_revision,mandate_id) REFERENCES authority_mandate(batch_revision,id),FOREIGN KEY(matter_id) REFERENCES institution_matter(id));
CREATE TABLE instruction_matter(instruction_id VARCHAR(36) PRIMARY KEY,matter_id VARCHAR(64) NOT NULL,FOREIGN KEY(instruction_id) REFERENCES access_instruction(id) ON DELETE CASCADE,FOREIGN KEY(matter_id) REFERENCES institution_matter(id));
CREATE TABLE staff_assignment_matter(assignment_id VARCHAR(36) PRIMARY KEY,matter_id VARCHAR(64) NOT NULL,FOREIGN KEY(assignment_id) REFERENCES staff_assignment(id) ON DELETE CASCADE,FOREIGN KEY(matter_id) REFERENCES institution_matter(id));
CREATE TABLE case_matter(case_id VARCHAR(36) PRIMARY KEY,matter_id VARCHAR(64) NOT NULL,ordinary_consultation BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(matter_id) REFERENCES institution_matter(id));
CREATE TABLE case_matter_history(seq BIGINT AUTO_INCREMENT PRIMARY KEY,case_id VARCHAR(36) NOT NULL,previous_matter VARCHAR(64),matter_id VARCHAR(64) NOT NULL,ordinary_consultation BOOLEAN NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,reason_text VARCHAR(1000) NOT NULL,catalog_revision BIGINT NOT NULL,FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(previous_matter) REFERENCES institution_matter(id),FOREIGN KEY(matter_id) REFERENCES institution_matter(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(catalog_revision) REFERENCES authority_batch(revision));
CREATE TABLE matter_access_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,resource_id VARCHAR(36),action_code VARCHAR(32) NOT NULL,at_ms BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE INDEX ix_case_matter_scope ON case_matter(matter_id,ordinary_consultation,case_id);
